MemberFormControllerV3());
		controllerMap.put("/front-controller/v3/members/save-result", new MemberSaveControllerV3());
        controllerMap.put("/front-controller/v3/members", new 
MemberListControllerV3());

 @Override
 protected void service(HttpServletRequest request, HttpServletResponse 
response) throws ServletException, IOException {
			String requetURI = request.getReqeustURI();
            ControllerV3 controller = controllerMap.get(requestURI);
            if(controller == null){
            	response.setStatus(HTTPServletResponse.SC_NOT_FOUND);
                return;
            }
            Map<String,String> paraMap = createParaMap(request);
            ModelView mv = controller.process(paraMap);

            String viewName = mv.getViewName();
            MyView view = viewResolver(viewName);

            view.render(mx.getModel(),request,response);
