                arr[i] = quiz.charAt(j);	// int형으로 배열을 선언했는데 char를 입력받고 있네?
                if(arr[i] == O){
                    cnt++;
                }
                else
                    cnt=0;
                score+=cnt;
            }
            System.out.println(score);    
        }

    }
}
```

